29	// a set of cookies with a key prefix of "$appName-request-header-$headerName",
30	// which will be added as an HTTP header to all requests.
31	export const getDefaultHeadersFromCookies = (cookieStr: any) => {
32	  const headerCookiePrefix = 'mlflow-request-header-';
33	  const parsedCookie = cookie.parse(cookieStr);
34	  if (!parsedCookie || Object.keys(parsedCookie).length === 0) {
35	    return {};
36	  }
37	  return Object.keys(parsedCookie)
38	    .filter((cookieName) => cookieName.startsWith(headerCookiePrefix))
39	    .reduce(
40	      (acc, cookieName) => ({
41	        ...acc,
42	        [cookieName.substring(headerCookiePrefix.length)]: parsedCookie[cookieName],
43	      }),
44	      {},
45	    );
46	};
