15	export const useCreateEvaluationDatasetMutation = ({
16	  onSuccess,
17	  onError,
18	}: {
19	  onSuccess?: () => void;
20	  onError?: (error: any) => void;
21	}) => {
22	  const queryClient = useQueryClient();
23	
24	  const { mutate: createEvaluationDatasetMutation, isLoading } = useMutation({
25	    mutationFn: async ({ datasetName, experimentIds }: CreateDatasetPayload) => {
26	      const requestBody = {
27	        name: datasetName,
28	        experiment_ids: experimentIds,
29	      };
30	
31	      const response = (await fetchAPI(getAjaxUrl('ajax-api/3.0/mlflow/datasets/create'), {
32	        method: 'POST',
33	        body: requestBody,
34	      })) as CreateDatasetResponse;
35	
36	      return response.dataset;
37	    },
38	    onSuccess: () => {
39	      queryClient.invalidateQueries({ queryKey: [SEARCH_EVALUATION_DATASETS_QUERY_KEY] });
40	      onSuccess?.();
41	    },
42	    onError: (error) => {
43	      onError?.(error);
44	    },
45	  });
46	
47	  return {
48	    createEvaluationDatasetMutation,
49	    isLoading,
50	  };
51	};
