export const LabelSchemaInputNumeric = ({
  input,
  value,
  onChange,
  componentId,
  disabled,
}: LabelSchemaInputNumericProps) => {
  return (
    <Input
      componentId={componentId}
      type="number"
      value={value === null || value === undefined ? '' : String(value)}
      min={input.min_value}
      max={input.max_value}
      disabled={disabled}
      onChange={(e) => {
        const nextValue = e.target.value;
        if (nextValue === '') {
          onChange(null);
        } else {
          onChange(Number(nextValue));
        }
      }}
    />
  );
};
