[metadata] {"type": "create", "filePath": "/workspace/repo/mlflow/server/js/src/experiment-tracking/components/label-schemas/widgets/LabelSchemaInputCategorical.tsx", "content": "import {
  DialogCombobox,
  DialogComboboxContent,
  DialogComboboxOptionList,
  DialogComboboxOptionListCheckboxItem,
  DialogComboboxOptionListSelectItem,
  DialogComboboxTrigger,
} from '@databricks/design-system';

type LabelSchemaInputCategoricalProps = {
  input: {
    options: string[];
    multi_select?: boolean;
  };
  value: string | string[] | null | undefined;
  onChange: (value: string | string[]) => void;
  componentId: string;
  label: string;
  disabled?: boolean;
};

/**
 * Renders a combobox (role="combobox") accessible by the `label` prop.
 * Single-select by default; multi-select when `input.multi_select` is true.
 */
export const LabelSchemaInputCategorical = ({
  input,
  value,
  onChange,
  componentId,
  label,
  disabled,
}: LabelSchemaInputCategoricalProps) => {
  const multiSelect = Boolean(input.multi_select);

  if (multiSelect) {
    const selectedValues = Array.isArray(value) ? value : [];

    const toggleOption = (option: string) => {
      if (selectedValues.includes(option)) {
        onChange(selectedValues.filter((item) => item !== option));
      } else {
        onChange([...selectedValues, option]);
      }
    };

    return (
      <DialogCombobox componentId={componentId} label={label} multiSelect value={selectedValues}>
        <DialogComboboxTrigger withInlineLabel={false} onClear={() => onChange([])} disabled={disabled} />
        <DialogComboboxContent>
          <DialogComboboxOptionList>
            {input.options.map((option) => (
              <DialogComboboxOptionListCheckboxItem
                key={option}
                value={option}
                checked={selectedValues.includes(option)}
                onChange={() => toggleOption(option)}
              >
                {option}
              </DialogComboboxOptionListCheckboxItem>
            ))}
          </DialogComboboxOptionList>
        </DialogComboboxContent>
      </DialogCombobox>
    );
  }

  const selectedValue = typeof value === 'string' ? value : '';

  return (
    <DialogCombobox componentId={componentId} label={label} value={selectedValue ? [selectedValue] : []}>
      <DialogComboboxTrigger withInlineLabel={false} onClear={() => onChange('')} disabled={disabled} />
      <DialogComboboxContent>
        <DialogComboboxOptionList>
          {input.options.map((option) => (
            <DialogComboboxOptionListSelectItem
              key={option}
              value={option}
              checked={option === selectedValue}
              onChange={() => onChange(option)}
            >
              {option}
            </DialogComboboxOptionListSelectItem>
          ))}
        </DialogComboboxOptionList>
      </DialogComboboxContent>
    </DialogCombobox>
  );
};
